def flatten(d: dict) -> dict:
    result = {}
    for key, value in d.items():
        new_key = f"{key}" if not isinstance(value, dict) else str(key)
        if isinstance(value, dict):
            nested = {f"{new_key}.{k}": v for k, v in value.items()}
            result.update(nested)
        else:
            result[new_key] = value
    return result
