def parse_row(line: str) -> list[str]:
    fields = []
    current = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Check for escaped quote ("") inside quotes
                if i + 1 < n and line[i + 1] == '"':
                    current.append('"')
                    i += 2
                    continue
                else:
                    in_quotes = False
                    i += 1
                    continue
            else:
                current.append(ch)
        else:
            if ch == '"':
                in_quotes = True
            elif ch == ',':
                fields.append(''.join(current).strip())
                current = []
            else:
                current.append(ch)
        i += 1
    # Append the final field (no trailing comma expected, but handle it anyway)
    fields.append(''.join(current).strip())
    return fields
