import re


def parse_money(s: str) -> float | None:
    if not isinstance(s, str):
        return None
    s = s.strip()
    if not s or s.lower() in {"n/a", "na"}:
        return None
    match = re.fullmatch(r"\s*\$?\s*([0-9][0-9,\.]*)(\.[0-9]+)?\s*", s)
    if not match:
        return None
    cleaned = match.group(1).replace(",", "")
    try:
        return float(cleaned)
    except ValueError:
        return None
